/**
 * Drives the real TSOA routes (src/generated/routes.ts, regenerated by init.sh) in-process.
 * Route test files must also mock '../../controllers/authentication' (see the route tests).
 *
 * Only getFederationService (plus any extraServices a test names) is available on
 * req.services: Write Mode and the audit browser must not touch AsyncQueryService or any
 * other query path (CONTRACTS §4.2).
 */
import { Ability } from '@casl/ability';
import express, {
    type ErrorRequestHandler,
    type RequestHandler,
} from 'express';
import { IncomingMessage, ServerResponse } from 'node:http';
import { Socket } from 'node:net';
import {
    buildAccount,
    defaultSessionUser,
} from '../../auth/account/account.mock';
import { RegisterRoutes } from '../../generated/routes';

export const PROJECT_UUID = '7a8b9c0d-0000-4000-8000-0000000000bb';
export const ORGANIZATION_UUID = defaultSessionUser.organizationUuid;
export const USER_UUID = defaultSessionUser.userUuid;
export const USER_EMAIL = defaultSessionUser.email;

export type RouteResponse = { status: number; body: any };

export const buildRouteApp = (
    federationService: unknown,
    extraServices: Record<string, unknown> = {},
) => {
    const account = buildAccount();
    account.user.ability = new Ability([
        { action: 'view', subject: 'Project' },
        { action: 'manage', subject: 'SqlRunner' },
        { action: 'manage', subject: 'Explore' },
    ]) as never;
    const touched: string[] = [];
    const services = new Proxy(
        {},
        {
            get: (_target, property) => {
                if (property === 'getFederationService') {
                    return () => federationService;
                }
                if (typeof property === 'string' && property in extraServices) {
                    return () => extraServices[property];
                }
                if (typeof property === 'string' && property.startsWith('get')) {
                    return () => {
                        touched.push(property);
                        throw new Error(
                            `ldq routes must only use getFederationService, not ${property}`,
                        );
                    };
                }
                return undefined;
            },
        },
    );
    const app = express();
    app.use((request, _response, next) => {
        Object.assign(request, {
            account,
            user: { ...defaultSessionUser, ability: account.user.ability },
            services,
        });
        next();
    });
    RegisterRoutes(app);
    const errors: ErrorRequestHandler = (error, _request, response, _next) => {
        response
            .status(error.status ?? error.statusCode ?? 500)
            .json({ status: 'error', error: { message: error.message } });
    };
    app.use(errors);

    const call = (
        method: string,
        path: string,
        body?: unknown,
    ): Promise<RouteResponse> =>
        new Promise((resolve) => {
            const request = new IncomingMessage(new Socket());
            request.method = method;
            request.url = path;
            request.headers = { 'content-type': 'application/json' };
            Object.assign(request, { body });
            const response = new ServerResponse(request);
            const capture: RequestHandler = (_request, res, next) => {
                res.json = (result) => {
                    resolve({ status: res.statusCode, body: result });
                    return res;
                };
                next();
            };
            const dispatch = express();
            dispatch.use(capture);
            dispatch.use(app);
            dispatch(request, response);
        });

    return { call, touched, account };
};

export const federationProject = (httpBaseUrl: string, flavor = 'federation') => ({
    projectUuid: PROJECT_UUID,
    organizationUuid: ORGANIZATION_UUID,
    name: 'Operations',
    warehouseConnection: {
        type: 'postgres',
        flavor,
        host: '127.0.0.1',
        port: 5433,
        user: 'lightdash-operations',
        password: 'test-password-not-real',
        dbname: 'operations',
        schema: 'public',
        identitySigningSecret: 'test-secret-not-real',
        httpBaseUrl,
    },
});

/** Builds the FederationService with the only two dependencies these tests pin. */
export const buildFederationService = (
    FederationService: any,
    {
        project,
        attributes,
    }: { project: unknown; attributes: Record<string, string[]> },
) =>
    new FederationService({
        projectModel: {
            getWithSensitiveFields: vi.fn(async () => project),
        },
        userAttributesModel: {
            getAttributeValuesForOrgMember: vi.fn(async () => attributes),
        },
    });
